class PoseAnswerCache{
  constructor(){this.mask=(1<<17)-1;this.x=new Float64Array(this.mask+1);this.y=new Float64Array(this.mask+1);this.tags=new Uint32Array(this.mask+1);this.answers=new Int32Array(this.mask+1);this.kinds=new Map();}
  tag(h,kind){const k=h+':'+(kind||'body');let t=this.kinds.get(k);if(t===undefined){t=this.kinds.size+1;this.kinds.set(k,t);}return t;}
  slot(x,y,tag){let h=Math.imul(Math.floor(x*1e6),0x9e3779b1)^Math.imul(Math.floor(y*1e6),0x85ebca6b)^Math.imul(tag,0xc2b2ae35);h^=h>>>16;h=Math.imul(h,0x85ebca6b);h^=h>>>13;return h&this.mask;}
  get(x,y,t){const i=this.slot(x,y,t);return this.tags[i]===t&&this.x[i]===x&&this.y[i]===y?this.answers[i]:undefined;}
  set(x,y,t,value){const i=this.slot(x,y,t);this.x[i]=x;this.y[i]=y;this.tags[i]=t;this.answers[i]=value;}
}
